KDPP3_PAYLOAD_BASE64
echo "$PAYLOAD_SHA256  $ROOT/payload.tar.gz" | sha256sum -c - >/dev/null || { echo FAIL_PAYLOAD_SHA256; exit 85; }
tar -xzf "$ROOT/payload.tar.gz" -C "$ROOT" || { echo FAIL_EXTRACT; exit 86; }
echo "PAYLOAD_OK sha256=$PAYLOAD_SHA256 bytes=$(stat -c %s "$ROOT/payload.tar.gz")"
"$PY" -I -B - "$ROOT" <<'KDPP3_VERIFY'
import hashlib, json, sys
root = sys.argv[1]
manifest = json.load(open(root + '/deploy_manifest.sha256.json'))
bad = [k for k, v in manifest.items() if hashlib.sha256(open(root + '/' + k, 'rb').read()).hexdigest() != v]
print('DEPLOY_MANIFEST members=%d mismatched=%d' % (len(manifest), len(bad)))
sys.exit(1 if bad else 0)
KDPP3_VERIFY
rc=$?; echo "VERIFY_EXIT=$rc"; [ "$rc" -eq 0 ] || exit 87
mkdir -p "$ROOT/runs" "$ROOT/runtime" "$ROOT/logs" || exit 88
rm -f "$ROOT/payload.tar.gz"
echo "WORKSPACE_FROZEN_MANIFEST_SHA256=$(sha256sum "$ROOT/workspace/frozen_members.sha256.json" | cut -c1-64)"
